// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.calendarimport timber.log.Timberimport android.Manifestimport android.app.Activityimport android.content.Contextimport android.content.Intentimport android.content.pm.PackageManagerimport android.net.Uriimport android.provider.Settingsimport androidx.core.content.ContextCompat/** * NOUS — Calendar Permission Handler (Module 14 v1.2 — Step 14.4). * * REAL implementation of calendar permission checking + requesting. * * ## Permission Matrix * * | Operation | Permission | Request Type | * |-----------|-----------|--------------| * | Read events (getNextEvent, getTodayEvents) | READ_CALENDAR | Runtime (API 23+) | * | Create event | WRITE_CALENDAR | Runtime (API 23+) | * | Update event | WRITE_CALENDAR | Runtime (API 23+) | * | Delete event | WRITE_CALENDAR | Runtime (API 23+) | * | Add reminder | WRITE_CALENDAR | Runtime (API 23+) | * * Both permissions are runtime permissions since API 23 — the user must grant * them via a system permission dialog. NOUS uses [ContextCompat.checkSelfPermission] * for the check (REAL Android API). * * ## Privacy * * Calendar permissions grant access to ALL of the user's calendars (across * all signed-in accounts). NOUS: * *   1. Requests permissions lazily — only when the user actually invokes a *      calendar command. *   2. Never copies calendar data into its own DB. All operations go through *      the system provider at call time. *   3. Never logs event content. Only event IDs + start times hit the logcat. * * @see <a href="https://developer.android.com/training/permissions/requesting">Request app permissions</a> */class CalendarPermissionHandler(    private val context: Context,) {    companion object {        private const val TAG = "CalendarPerms"    }    /**     * Check if READ_CALENDAR is granted (REAL ContextCompat.checkSelfPermission).     *     * Required for: [CalendarReader.getNextEvent], [CalendarReader.getTodayEvents],     *                [CalendarReader.getEventsInRange], [CalendarReader.getEventReminders].     */    fun hasReadCalendarPermission(): Boolean {        return ContextCompat.checkSelfPermission(            context,            Manifest.permission.READ_CALENDAR,        ) == PackageManager.PERMISSION_GRANTED    }    /**     * Check if WRITE_CALENDAR is granted (REAL ContextCompat.checkSelfPermission).     *     * Required for: [CalendarWriter.createEvent], [CalendarWriter.updateEvent],     *                [CalendarWriter.deleteEvent], [CalendarWriter.addReminder].     */    fun hasWriteCalendarPermission(): Boolean {        return ContextCompat.checkSelfPermission(            context,            Manifest.permission.WRITE_CALENDAR,        ) == PackageManager.PERMISSION_GRANTED    }    /**     * Check if both READ + WRITE calendar permissions are granted.     *     * Most calendar operations need both — e.g., [CalendarWriter.createEventWithReminder]     * needs WRITE to insert the event + WRITE to insert the reminder.     */    fun hasFullCalendarAccess(): Boolean {        return hasReadCalendarPermission() && hasWriteCalendarPermission()    }    /**     * Check if at least one calendar permission is granted (read-only mode).     *     * Useful for `getNextEvent` / `getTodayEvents` which only need READ.     */    fun hasReadAccess(): Boolean = hasReadCalendarPermission()    /**     * Get the list of missing permissions for a read operation.     *     * @return list of missing permission strings (empty if READ_CALENDAR is granted).     */    fun getMissingReadPermissions(): List<String> {        val missing = mutableListOf<String>()        if (!hasReadCalendarPermission()) {            missing.add(Manifest.permission.READ_CALENDAR)        }        return missing    }    /**     * Get the list of missing permissions for a write operation.     *     * @return list of missing permission strings (empty if WRITE_CALENDAR is granted).     */    fun getMissingWritePermissions(): List<String> {        val missing = mutableListOf<String>()        if (!hasWriteCalendarPermission()) {            missing.add(Manifest.permission.WRITE_CALENDAR)        }        return missing    }    /**     * Get a user-friendly message about missing read permissions.     */    fun getMissingReadPermissionsMessage(): String {        val missing = getMissingReadPermissions()        if (missing.isEmpty()) return ""        return "I need calendar read permission to see your upcoming events. " +               "Please grant it in Settings."    }    /**     * Get a user-friendly message about missing write permissions.     */    fun getMissingWritePermissionsMessage(): String {        val missing = getMissingWritePermissions()        if (missing.isEmpty()) return ""        return "I need calendar write permission to create or modify events. " +               "Please grant it in Settings."    }    /**     * Launch the system Settings page for the app's calendar permissions.     *     * Used when the user has permanently denied the permission (so the     * runtime permission dialog won't show anymore). On the Settings page,     * the user can manually toggle READ_CALENDAR / WRITE_CALENDAR.     *     * @param activity the current Activity (for launching the Settings intent).     * @return true if the Settings page was launched successfully.     */    fun openCalendarSettings(activity: Activity): Boolean {        return try {            val intent = Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {                data = Uri.fromParts("package", context.packageName, null)                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)            }            activity.startActivity(intent)            Timber.tag(TAG).i("Launched app details Settings page for calendar permissions.")            true        } catch (e: Exception) {            Timber.tag(TAG).w("Could not launch app details Settings.", e)            false        }    }}